using System.Collections.Concurrent;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.DataProtection;
using Nuzul;
if (args.Length == 2 && args[0] == "--generate-cloud-keyring") { CloudHosting.GenerateKeyRing(args[1]); return; }
DemoHosting.Validate(); TesterWorkflow.ValidateVerificationWorkspace(); var builder = WebApplication.CreateBuilder(args); var cloud = new CloudHosting(); builder.WebHost.UseUrls(Environment.GetEnvironmentVariable("NUZUL_API_URL") ?? "http://127.0.0.1:5188"); builder.WebHost.ConfigureKestrel(o => o.Limits.MaxRequestBodySize = 3_000_000); var keyDir = Path.Combine(Environment.GetEnvironmentVariable("NUZUL_DATA_DIR") ?? Path.Combine(AppContext.BaseDirectory, "data"), "keys"); Directory.CreateDirectory(keyDir); if (!OperatingSystem.IsWindows()) File.SetUnixFileMode(keyDir, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute); builder.Services.AddDataProtection().SetApplicationName("NuzulQAStudio").PersistKeysToFileSystem(new DirectoryInfo(keyDir)); cloud.Configure(builder); builder.Services.AddSingleton<Store>(); builder.Services.AddSingleton<Jobs>(); var app = builder.Build();
if (cloud.Enabled) { app.Use(async (ctx, next) => { ctx.Response.Headers["Cache-Control"] = "no-store"; ctx.Response.Headers["Referrer-Policy"] = "no-referrer"; ctx.Response.Headers["X-Content-Type-Options"] = "nosniff"; ctx.Request.Scheme = "https"; ctx.Request.Host = new HostString(new Uri(cloud.Origin).Authority); await next(); }); app.UseAuthentication(); }
 var key = Environment.GetEnvironmentVariable("NUZUL_STUDIO_KEY"); if (!cloud.Enabled && !DemoHosting.Enabled && (string.IsNullOrWhiteSpace(key) || key.Length < 16)) throw new InvalidOperationException("NUZUL_STUDIO_KEY (minimum 16 characters) is required. Use scripts/start.sh.");
app.Use(async (ctx, next) => { try { if (ctx.Request.Path.StartsWithSegments("/api") && ctx.Request.Path != "/api/health" && ctx.Request.Path != "/api/auth/config") { if (cloud.Enabled) { if (!cloud.IsOwner(ctx.User)) { ctx.Response.StatusCode = 401; await ctx.Response.WriteAsJsonAsync(new { error = "Sign in with the permitted Google account." }); return; } if (!HttpMethods.IsGet(ctx.Request.Method) && !HttpMethods.IsHead(ctx.Request.Method) && !cloud.AcceptMutation(ctx.Request)) { ctx.Response.StatusCode = 403; await ctx.Response.WriteAsJsonAsync(new { error = "Same-origin request required." }); return; } } else if (DemoHosting.Enabled) { if (!DemoHosting.Accept(ctx)) { ctx.Response.StatusCode = 403; await ctx.Response.WriteAsJsonAsync(new { error = "Local same-origin demo request required." }); return; } } else { var supplied = ctx.Request.Headers["X-Studio-Key"].ToString(); if (!CryptographicOperations.FixedTimeEquals(SHA256.HashData(Encoding.UTF8.GetBytes(supplied)), SHA256.HashData(Encoding.UTF8.GetBytes(key ?? "")))) { ctx.Response.StatusCode = 401; await ctx.Response.WriteAsJsonAsync(new { error = "Studio key required" }); return; } } } ctx.Response.Headers["X-Content-Type-Options"] = "nosniff"; ctx.Response.Headers["Cache-Control"] = "no-store"; await next(); } catch (Exception ex) { if (ctx.Response.HasStarted) return; ctx.Response.StatusCode = ex is KeyNotFoundException ? 404 : 400; await ctx.Response.WriteAsJsonAsync(new { error = cloud.Enabled ? "Request could not be completed. Check the input or deployment configuration." : SafeHttp.Mask(ex.Message, key ?? "") }); } });
cloud.Attach(app); DemoHosting.Seed(app.Services.GetRequiredService<Store>());
if (cloud.Enabled || cloud.OnDevice || DemoHosting.Enabled) { app.UseDefaultFiles(); app.UseStaticFiles(); if (cloud.Enabled) app.UseHsts(); }
app.MapGet("/api/health", () => new { status = "ok", application = "Sarj QA Studio", version = "1.0", verificationWorkspace = Environment.GetEnvironmentVariable("SARJ_VERIFICATION_MODE") == "isolated" });
app.MapGet("/api/projects", (bool? archived, Store s) => s.All().Where(p => p.Archived == (archived == true)).Select(s.Public));
app.MapPut("/api/projects/{id}/archive", (string id, ArchiveRequest input, Store s) => { lock(s.Gate) { var p = s.Project(id); p.Archived = input.Archived; p.ArchiveReason = input.Archived ? "Archived by workspace owner" : ""; s.Save(p); return s.Public(p); } });
app.MapPost("/api/projects/{id}/checks", (string id, ManualCheckRequest input, Store s) => { lock(s.Gate) { var p = s.Project(id); TesterWorkflow.AddCheck(p, input); s.Save(p); return s.Public(p); } });
app.MapPost("/api/projects/{id}/observations", (string id, ManualObservationRequest input, Store s) => { lock(s.Gate) { var p = s.Project(id); TesterWorkflow.Record(p, input); s.Save(p); return s.Public(p); } });
app.MapPost("/api/projects", (CreateProject body, Store s) => { if (string.IsNullOrWhiteSpace(body.Name) || body.Name.Length > 180) throw new InvalidOperationException("Project name is required (max180)."); var p = new Project { Name = body.Name.Trim(), Settings = new() { BaseUrl = "" } }; s.Save(p); return s.Public(p); });
app.MapGet("/api/projects/{id}", (string id, Store s) => s.Public(s.Project(id)));
app.MapPost("/api/projects/{id}/sources", async (string id, Source input, Store s) => { lock (s.Gate) { var p = s.Project(id); if (p.Sources.Count >= 30) throw new InvalidOperationException("Maximum30 sources per project"); if (input.Content.Length > 2_000_000 || input.Name.Length > 240 || input.Type.Length > 50) throw new InvalidOperationException("Source exceeds input limits"); } if (input.Type.Equals("url", StringComparison.OrdinalIgnoreCase)) { var u = await SafeHttp.Validate(input.Content); using var c = SafeHttp.Client(); using var resp = await c.GetAsync(u, HttpCompletionOption.ResponseHeadersRead); resp.EnsureSuccessStatusCode(); input.Content = await SafeHttp.ReadBounded(resp.Content, default, 2_000_000); input.Type = "openapi"; input.Name = string.IsNullOrWhiteSpace(input.Name) ? u.AbsoluteUri : input.Name; } lock (s.Gate) { var p = s.Project(id); input.Id = Guid.NewGuid().ToString("N"); input.Content = SafeHttp.Mask(input.Content, p.Settings.AuthToken); Analysis.Extract(p, input); p.Sources.Add(input); s.Save(p); return s.Public(p); } });
app.MapPost("/api/projects/{id}/analyze",async(string id,AnalyzeRequest request,Store s)=>{if(!request.UseAi)throw new InvalidOperationException("Source analysis requires explicit useAi:true consent");var snapshot=s.Project(id);var drafts=await AiAnalysis.Analyze(snapshot,request.UseFree?Ai.FreeProvider():Ai.Provider(s));lock(s.Gate){var current=s.Project(id);foreach(var draft in drafts)if(current.Sources.Any(src=>src.Id==draft.SourceId)&&!current.Requirements.Any(r=>r.SourceId==draft.SourceId&&r.Text==draft.Text&&r.Status==draft.Status))current.Requirements.Add(draft);s.Save(current);return s.Public(current);}});
app.MapPost("/api/projects/{id}/design", async (string id, DesignRequest request, Store s) => { Project p; lock (s.Gate) { p = s.Project(id); if (request.TestId != null) { var selected = p.TestCases.FirstOrDefault(t => t.Id == request.TestId) ?? throw new KeyNotFoundException("Test not found"); p.TestCases.Remove(selected); } Analysis.Design(p, request.IncludeLowerPriorities); } if (request.UseAi) await Ai.Design(p, Ai.Provider(s)); lock (s.Gate) { var current = s.Project(id); if (current.TestCases.Any(t => t.Approved)) foreach (var t in current.TestCases.Where(t => t.Approved && t.Id != request.TestId)) { p.TestCases.RemoveAll(x => x.Id == t.Id); p.TestCases.Add(t); } s.Save(p); } return s.Public(p); });
app.MapPut("/api/projects/{id}/tests/{testId}", (string id, string testId, TestCase input, Store s) => { lock (s.Gate) { var p = s.Project(id); var i = p.TestCases.FindIndex(t => t.Id == testId); if (i < 0) throw new KeyNotFoundException("Test case not found"); if (input.Body.Length > 100000 || input.Steps.Count > 100 || input.Assertions.Count > 100) throw new InvalidOperationException("Test exceeds safe limits"); if (!p.Requirements.Any(r => r.Id == input.RequirementId)) throw new InvalidOperationException("Requirement reference must exist"); input.Id = testId; input.Method = input.Method.ToUpperInvariant(); p.TestCases[i] = input; s.Save(p); return s.Public(p); } });
app.MapPut("/api/projects/{id}/settings", async (string id, Settings input, Store s) => { await SafeHttp.Validate(input.BaseUrl); if (!Jobs.Adapters.ContainsKey(input.Language)) throw new InvalidOperationException("Unsupported adapter"); if (input.AuthToken.Length > 4096) throw new InvalidOperationException("Credential too long"); lock (s.Gate) { var p = s.Project(id); if (input.AuthToken == "[STORED]") input.AuthToken = p.Settings.AuthToken; p.Settings = input; s.Save(p); return s.Public(p); } });
app.MapPut("/api/projects/{id}/defects/{evidenceReference}", (string id, string evidenceReference, Defect input, Store s) => { lock (s.Gate) { var p = s.Project(id); var defect = p.Defects.FirstOrDefault(d => d.EvidenceReference == evidenceReference) ?? throw new KeyNotFoundException("Confirmed failure evidence not found"); if (input.Severity is not ("Needs triage" or "Critical" or "High" or "Medium" or "Low" or "Major" or "Minor" or "Trivial")) throw new InvalidOperationException("Invalid severity"); if (input.Status is not ("Open" or "In Progress" or "In progress" or "Resolved" or "Closed" or "Rejected")) throw new InvalidOperationException("Invalid defect status"); if (input.Title.Length > 500 || input.Description.Length > 20000 || input.ReproductionSteps.Count > 100) throw new InvalidOperationException("Defect content exceeds limit"); input.BugId = defect.BugId; input.EvidenceReference = evidenceReference; p.Defects[p.Defects.IndexOf(defect)] = input; s.Save(p); return s.Public(p); } });
app.MapGet("/api/projects/{id}/preflight", async (string id, Store s) => await Jobs.Preflight(s.Project(id)));
app.MapPost("/api/projects/{id}/runs", (string id, RunRequest request, Store s, Jobs jobs) => { var run = jobs.Start(id, request, s); return s.Public(s.Project(id)).Runs.First(r => r.Id == run.Id); });
app.MapGet("/api/projects/{id}/runs/{runId}", (string id, string runId, Store s) => s.Public(s.Project(id)).Runs.FirstOrDefault(r => r.Id == runId) ?? throw new KeyNotFoundException("Run not found"));
app.MapPost("/api/projects/{id}/runs/{runId}/cancel", (string id, string runId, Store s, Jobs jobs) => { jobs.Cancel(runId); lock (s.Gate) { var p = s.Project(id); var r = p.Runs.FirstOrDefault(x => x.Id == runId) ?? throw new KeyNotFoundException("Run not found"); if (r.Status == "Running") r.Status = "Cancelled"; s.Save(p); return s.Public(p).Runs.First(x => x.Id == runId); } });
app.MapPut("/api/projects/{id}/runs/{runId}/results/{testId}/review", (string id, string runId, string testId, ReviewRequest req, Store s) => { if (req.Outcome is not ("Passed" or "Failed" or "Blocked" or "Skipped" or "Needs Review")) throw new InvalidOperationException("Invalid review outcome"); if (req.Observations.Length > 20000 || (req.Evidence?.Length ?? 0) > 1000000) throw new InvalidOperationException("Review exceeds limit"); lock (s.Gate) { var p = s.Project(id); var r = p.Runs.FirstOrDefault(r => r.Id == runId) ?? throw new KeyNotFoundException("Run not found"); var e = r.Results.FirstOrDefault(x => x.TestCaseId == testId) ?? throw new KeyNotFoundException("Result not found"); if (e.Outcome == "Blocked" && req.Outcome == "Failed") throw new InvalidOperationException("Environment blocks cannot become product defects through review"); e.ReviewedOutcome = req.Outcome; if (e.Outcome == "Needs Review" && e.Response.Status == 0 && string.IsNullOrEmpty(e.Request.Url)) { e.Outcome = req.Outcome; e.AssertionOutcome = "Human observation; not an automated deterministic assertion"; } e.Observations = SafeHttp.Mask(req.Observations, p.Settings.AuthToken); e.AttachedEvidence = SafeHttp.Mask(req.Evidence ?? "", p.Settings.AuthToken); e.Reviewed = true; s.Save(p); return s.Public(p).Runs.First(x => x.Id == runId); } });
app.MapPost("/api/projects/{id}/retrieve", (string id, RetrieveRequest req, Store s) => Analysis.Retrieve(s.Public(s.Project(id)), req.Query));
app.MapGet("/api/projects/{id}/reports/{format}", (string id, string format, string? lang, Store s) => { var p = s.Public(s.Project(id)); return format switch { "summary" => Results.File(Encoding.UTF8.GetBytes(TesterReport.Html(p, lang ?? "ar")), "text/html; charset=utf-8", "sarj-tester-report.html"), "json" => Results.File(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(Reports.Document(p), new JsonSerializerOptions(Store.Json) { WriteIndented = true })), "application/json", "sarj-report.json"), "html" => Results.File(Encoding.UTF8.GetBytes(Reports.Html(p, lang ?? "en")), "text/html; charset=utf-8", "sarj-report.html"), "rtf" => Results.File(Encoding.ASCII.GetBytes(Reports.Rtf(p, lang ?? "en")), "application/rtf", "sarj-report.rtf"), _ => throw new InvalidOperationException("Format must be json, html or rtf") }; });
app.MapGet("/api/settings", (Store s) => { var p = Ai.Provider(s); return new { p.ProviderUrl, p.Model, p.Enabled, apiKey = p.ApiKey.Length > 0 ? "[STORED]" : "", hasApiKey = p.ApiKey.Length > 0 }; });
app.MapPut("/api/settings", async (ProviderSettings p, Store s) => { if (p.Enabled) { var u = await SafeHttp.Validate(p.ProviderUrl); if (u.Scheme != "https") throw new InvalidOperationException("AI provider requires HTTPS"); if (string.IsNullOrWhiteSpace(p.Model)) throw new InvalidOperationException("AI model is required"); } if (p.ApiKey == "[STORED]") p.ApiKey = s.Get<ProviderSettings>("provider")?.ApiKey ?? ""; s.Save("provider", p); return new { p.ProviderUrl, p.Model, p.Enabled, apiKey = p.ApiKey.Length > 0 ? "[STORED]" : "", hasApiKey = p.ApiKey.Length > 0 }; });
app.MapGet("/presentation", () => Results.Redirect("/presentation/index.html"));
if (cloud.Enabled || cloud.OnDevice || DemoHosting.Enabled) app.MapFallbackToFile("index.html");
app.Run();
record CreateProject(string Name); record DesignRequest(bool IncludeLowerPriorities = false, bool UseAi = false, string? TestId = null); record RetrieveRequest(string Query); public record RunRequest(List<string>? TestIds = null, string Language = "csharp", string Mode = "Automated", bool AllowMutations = false); record ReviewRequest(string Outcome, string Observations, string? Evidence = null);

record AnalyzeRequest(bool UseAi=false,bool UseFree=false);

record ArchiveRequest(bool Archived);
